-- Venue Live Guest "Kelahiran Bayi Laki-laki". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara kelahiran), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'kelahiran', 'Kelahiran Bayi Laki-laki', 'kelahiran', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 153, 'center 38%',
  $t${"name":"Kelahiran Bayi Laki-laki","orn":"diamond","ui":{"ivory":"#F7F9FD","white":"#FFFFFF","soft":"#DCE6F5","soft2":"#8FA8D6","accent":"#3F5FA3","deep":"#1F2F5A","ink":"#1F2F5A","mute":"#6F7FA3","line":"#D3DDEF","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FAFBFF","ink":"#1F2F5A","accent":"#3F5FA3","gold":"#C9A24A","leaf":"#DCE6F5","hbg":"rgba(247,249,253,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(31,47,90,.9)","acc":"#F2D27A","on":"#1F2F5A"},"scr":{"wine":"#1F2F5A","veil":"247,249,253"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'kelahiran');
